    /**
     * Method to retrieve the Policy via an FindPolicyQuery
     * @return 	query	FindPolicyQuery
     */
    @SuppressWarnings("unused")
    public Policy find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Policy - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Policys
     *
     * @param	query	FindAllPolicyQuery 
     * @return 	List<Policy> 
     */
    @SuppressWarnings("unused")
    public List<Policy> findAll( FindAllPolicyQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Policy - {0}", exc.getMessage() );
    	}
    	return null;
    }


